import process from 'node:process'

export const createCallbackHandler = () => {
  /**
   * Pending nested `context.registerCallback()` calls, keyed by correlation id. Each entry
   * holds the resolve/reject of the Promise returned to the user's handler; it is
   * settled when the matching `callback-response` arrives from the parent.
   * @type {Map<string, {resolve: (value: unknown) => void, reject: (reason: Error) => void, timer: ReturnType<typeof setTimeout> | undefined}>}
   */
  const pendingResponses = new Map([])
  const pendingRequests = new Map([])
  let nextAttempt = 0

  // Register a callback with the parent process. Returns a Promise that resolves when the callback is invoked, or rejects if the callback times out.
  const register = ({callbackId, name, timeout}) => {
    return new Promise((resolve, reject) => {
      const timer = timeout
        ? setTimeout(() => {
            cancel(callbackId)
            reject(new Error(`Callback ${callbackId} timed out after ${timeout}ms`))
          }, timeout)
        : undefined

      pendingResponses.set(callbackId, {resolve, reject, timer})
      process.send(JSON.stringify({type: 'callback-register', callbackId, name}))
    })
  }

  /**
   * Handle a response from the parent process for a registered callback. This is called when the parent process sends a `callback-response` message.
   */
  const handleResponse = (msg) => {
    if (msg.attempt !== undefined) {
      const entry = removeRequest(msg.attempt)

      if (!entry) {
        return
      }

      if (msg.ok) {
        entry.resolve(msg.result)
      } else {
        entry.reject(new Error(msg.error.message))
      }
      return
    }

    const pendingEntry = pendingResponses.get(msg.callbackId)
    if (!pendingEntry) return

    pendingResponses.delete(msg.callbackId)
    clearTimeout(pendingEntry?.timer)
    if (msg.ok) {
      pendingEntry.resolve(msg.result)
      return
    }

    const {message, stack, name} = msg.error
    const error = new Error(message)
    error.stack = stack
    error.name = name
    pendingEntry.reject(error)
  }

  /**
   * Handle a request from the parent process to invoke a registered callback. This is called when the parent process sends a `callback-request` message.
   */
  const handleRequest = (request, next) => {
    // Match the request from the callback.sucess or callback.failure sanity client functions
    const CALLBACK_URL =
      /^https?:\/\/[^/?#]+\/v[^/?#]+\/functions\/durables\/callback\/([^/?#]+)\/(success|failure)(?:[?#].*)?$/

    const match = request.method?.toUpperCase() === 'POST' && CALLBACK_URL.exec(request.url)
    if (!match) {
      return next(request)
    }

    const [, callbackId, outcome] = match
    const {body, timeout} = request
    if (typeof body !== 'string') {
      throw new TypeError('Callback body must be serialized JSON')
    }

    const timeoutMs = typeof timeout === 'object' && timeout !== null ? timeout.total : timeout
    const signals = [request.signal, timeoutMs > 0 && AbortSignal.timeout(timeoutMs)].filter(
      Boolean,
    )

    const signal = signals.length > 0 ? AbortSignal.any(signals) : undefined
    signal?.throwIfAborted()

    return new Promise((resolve, reject) => {
      const attempt = ++nextAttempt
      const onAbort = () => removeRequest(attempt)?.reject(signal.reason)
      pendingRequests.set(attempt, {
        callbackId,
        resolve,
        reject,
        cleanup: () => signal?.removeEventListener('abort', onAbort),
      })
      signal?.addEventListener('abort', onAbort, {once: true})
      try {
        process.send(
          JSON.stringify({type: 'callback-request', callbackId, attempt, outcome, body}),
          (error) => {
            if (error) removeRequest(attempt)?.reject(error)
          },
        )
      } catch (error) {
        removeRequest(attempt)?.reject(error)
      }
    })
  }

  /**
   * Remove a pending request from the map and clean up its resources. This is called when a request is completed or aborted.
   */
  const removeRequest = (attempt) => {
    const entry = pendingRequests.get(attempt)
    if (!entry) {
      return
    }

    pendingRequests.delete(attempt)
    entry.cleanup()
    return entry
  }

  process.once('disconnect', () => {
    const error = new Error('Local callback IPC disconnected')
    for (const attempt of pendingRequests.keys()) removeRequest(attempt)?.reject(error)
  })

  /**
   * Cancel a pending callback request. This is called when the parent process sends a `callback-cancel` message.
   */
  const cancel = (callbackId) => {
    const pendingEntry = pendingResponses.get(callbackId)
    if (!pendingEntry) return
    pendingResponses.delete(callbackId)
    clearTimeout(pendingEntry?.timer)
    process.send(JSON.stringify({type: 'callback-cancel', callbackId}))
  }

  return {
    cancel,
    register,
    handleRequest,
    handleResponse,
    removeRequest,
  }
}
